import math

def bce(y_true: list[float], y_prob: list[float]) -> float:
    eps = 1e-12
    total = 0.0
    for y, p in zip(y_true, y_prob):
        p = min(max(p, eps), 1.0 - eps)
        total += -(y * math.log(p) + (1.0 - y) * math.log(1.0 - p))
    return float(total / len(y_true))
